// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title MobileBackendOracle - Decryption verification for mobile API requests
/// @notice Validates encrypted payloads from mobile clients via reverse proxy
contract MobileBackendOracle is Ownable {

    uint256 private constant BLOCK_SIZE = 16;
    uint256 private constant MAX_PAYLOAD_BLOCKS = 8;

    mapping(address => uint256) public nonces;
    mapping(bytes32 => bool) public processedRequests;
    mapping(address => uint256) public balances;

    event RequestProcessed(address indexed user, bytes32 requestId, bool success);
    event ValidationResult(address indexed user, uint8 status);
    event BalanceUpdated(address indexed user, uint256 newBalance);

    error InvalidPayloadLength();
    error RequestAlreadyProcessed();
    error InsufficientBalance();

    struct DecryptionContext {
        bytes16 iv;
        bytes ciphertext;
        uint256 timestamp;
        address sender;
    }

    constructor() Ownable(msg.sender) {}

    function deposit() external payable {
        balances[msg.sender] += msg.value;
        emit BalanceUpdated(msg.sender, balances[msg.sender]);
    }

    /// @notice Validates CBC padding on decrypted payload from reverse proxy
    /// @param encryptedPayload The AES-CBC encrypted request from mobile client
    /// @param proxySignature Signature from the reverse proxy attestation
    /// @return requestId The processed request identifier
    function submitEncryptedRequest(
        bytes calldata encryptedPayload,
        bytes calldata proxySignature
    ) external returns (bytes32 requestId) {
        if (encryptedPayload.length == 0 || encryptedPayload.length % BLOCK_SIZE != 0) {
            revert InvalidPayloadLength();
        }
        if (encryptedPayload.length > BLOCK_SIZE * (MAX_PAYLOAD_BLOCKS + 1)) {
            revert InvalidPayloadLength();
        }

        requestId = keccak256(abi.encodePacked(msg.sender, nonces[msg.sender], block.timestamp));

        if (processedRequests[requestId]) {
            revert RequestAlreadyProcessed();
        }

        DecryptionContext memory ctx = DecryptionContext({
            iv: bytes16(encryptedPayload[:16]),
            ciphertext: encryptedPayload[16:],
            timestamp: block.timestamp,
            sender: msg.sender
        });

        uint8 validationStatus = _validateDecryptedPayload(ctx, proxySignature);

        // Unified response: only success or generic failure
        // No distinction between padding errors and other failures
        if (validationStatus == 1) {
            processedRequests[requestId] = true;
            nonces[msg.sender]++;
            emit RequestProcessed(msg.sender, requestId, true);
            emit ValidationResult(msg.sender, 1);
        } else {
            // Single failure path - no information leakage about failure reason
            emit ValidationResult(msg.sender, 0);
            emit RequestProcessed(msg.sender, requestId, false);
        }

        return requestId;
    }

    /// @dev Internal payload validation with constant-time padding check
    function _validateDecryptedPayload(
        DecryptionContext memory ctx,
        bytes calldata proxySignature
    ) internal view returns (uint8) {
        // Simulate decryption by deriving plaintext from proxy-attested data
        bytes memory simulatedPlaintext = _deriveFromProxy(ctx, proxySignature);

        if (simulatedPlaintext.length == 0) {
            return 0; // Generic failure
        }

        // Verify MAC FIRST (Encrypt-then-MAC order)
        bytes32 computedMac = keccak256(
            abi.encodePacked(ctx.iv, ctx.ciphertext, ctx.sender, ctx.timestamp)
        );

        if (simulatedPlaintext.length < BLOCK_SIZE + 32) {
            return 0; // Generic failure
        }

        // PKCS#7 padding validation - constant time
        uint8 lastByte = uint8(simulatedPlaintext[simulatedPlaintext.length - 1]);

        // Accumulate validity without early return
        uint256 paddingValid = 1;

        if (lastByte == 0 || lastByte > uint8(BLOCK_SIZE)) {
            paddingValid = 0;
        }

        // Check all padding bytes - always iterate full BLOCK_SIZE
        for (uint256 i = 0; i < BLOCK_SIZE; i++) {
            if (i < lastByte) {
                if (uint8(simulatedPlaintext[simulatedPlaintext.length - 1 - i]) != lastByte) {
                    paddingValid = 0;
                }
            }
        }

        // Extract expected MAC from the decrypted content.
        // Guard the offset arithmetic to prevent uint256 underflow and an
        // out-of-bounds inline-assembly read when lastByte is untrusted/oversized.
        // The out-of-range case folds into paddingValid so the unified single
        // failure path (no distinction between failure reasons) is preserved.
        bytes32 expectedMac;
        // Require enough room: length >= lastByte + 32 so macOffset does not underflow.
        if (uint256(lastByte) + 32 <= simulatedPlaintext.length) {
            uint256 macOffset = simulatedPlaintext.length - lastByte - 32;
            assembly {
                expectedMac := mload(add(add(simulatedPlaintext, 32), macOffset))
            }
        } else {
            paddingValid = 0;
        }

        // Both MAC and padding must be valid - single decision point
        if (paddingValid == 1 && computedMac == expectedMac) {
            return 1; // Success
        }

        return 0; // Generic failure - no distinction between padding/MAC errors
    }

    /// @dev Derives simulated plaintext from proxy attestation
    function _deriveFromProxy(
        DecryptionContext memory ctx,
        bytes calldata proxySignature
    ) internal view returns (bytes memory) {
        if (proxySignature.length < 64) {
            return new bytes(0);
        }

        // Simulate the reverse proxy providing decrypted content
        // In production, this would verify the proxy's TEE attestation
        bytes memory result = new bytes(ctx.ciphertext.length);

        for (uint256 i = 0; i < ctx.ciphertext.length && i < proxySignature.length - 64; i++) {
            result[i] = proxySignature[64 + i];
        }

        // Fill remaining with proxy-derived data
        if (ctx.ciphertext.length > proxySignature.length - 64) {
            bytes32 filler = keccak256(abi.encodePacked(proxySignature[:64], ctx.sender));
            for (uint256 i = proxySignature.length - 64; i < ctx.ciphertext.length; i++) {
                result[i] = bytes1(filler[i % 32]);
            }
        }

        return result;
    }

    /// @notice Query interface for reverse proxy health checks
    function getValidationGasEstimate(
        bytes calldata encryptedPayload
    ) external view returns (uint256) {
        if (encryptedPayload.length % BLOCK_SIZE != 0) return 0;
        uint256 blocks = encryptedPayload.length / BLOCK_SIZE;
        return 21000 + (blocks * 3200) + 15000;
    }
}
